// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 token;
    Maker1271 maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new MockERC20();
        maker = new Maker1271();
    }

    function testFuzz_property(uint256 strike, uint256 premium, uint256 nonce, address taker) public {
        vm.assume(taker != address(0) && taker != address(c) && taker != address(token) && taker != address(maker));
        strike = bound(strike, 1, type(uint256).max);
        premium = bound(premium, 1, type(uint256).max);

        PuttyV2.Order memory order;
        order.maker = address(maker);
        order.isCall = true;
        order.isLong = false;
        order.baseAsset = address(token);
        order.strike = strike;
        order.premium = premium;
        order.duration = 1 days;
        order.expiration = block.timestamp + 100 days;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        bytes memory sig = "";
        vm.prank(taker);
        c.fillOrder(order, sig, new uint256[](0));

        bytes32 positionId = c.hashOppositeOrder(order);

        bool ok;
        address owner;
        try c.ownerOf(uint256(positionId)) returns (address o) {
            ok = true;
            owner = o;
        } catch {
            ok = false;
        }
        assertTrue(ok && owner == taker);
    }
}

contract Maker1271 {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

